#include <iostream>

using namespace std;

int main() {
    int n;
    cin >> n;

    long long product = 1;
    for (int i = 0; i < n; ++i) {
        int a;
        cin >> a;
        if (product * a > 1000000) {
            cout << ">1000000" << endl;
            return 0;
        }
        product *= a;
    }

    cout << product << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            char ch;
            if (j == 0 || j == n - 1) {
                ch = '|';
            } else if (i == 0 || i == n - 1 || i == n / 2) {
                ch = '-';
            } else {
                ch = 'x';
            }
            cout << ch;
        }
        cout << endl;
    }

    return 0;
}
